fn enqueue(q: &mut LinkedList[Int], item: Int) -> Unit {
  q.push_back(item);
}

fn dequeue(q: &mut LinkedList[Int]) -> Option[Int] {
  return q.pop_front();
}

fn main() -> Int {
  var q = LinkedList[Int]();
  enqueue(&mut q, 1);
  enqueue(&mut q, 2);
  enqueue(&mut q, 3);
  var sum = 0;
  while !q.is_empty() {
    match dequeue(&mut q) {
      Some(n) => { sum = sum + n; }
      None => { }
    }
  }
  return sum;
}
